	draw_arc(look_center, 78.0, 0.0, TAU, 48, Color(0.65, 0.78, 1.0, 0.75), 2.0)
	var look_knob := look_center + Vector2(look_stick_value.x, -look_stick_value.y) * 56.0
	draw_circle(look_knob, 29.0, Color(0.42, 0.63, 1.0, 0.72))

