		var npc_key := str(npc_variant.get("key", "peq:npc:%d" % int(npc_variant.get("id", 0))))
		if npc_key.is_empty() or npc_keys.has(npc_key):
			_fail("Duplicate or empty NPC definition key: %s" % npc_key)
			return false
		npc_keys[npc_key] = true
