func xp_threshold(target_level: int) -> int:
	var hell_modifier := 1.0
	if target_level >= 31 and target_level <= 35:
		hell_modifier = 1.1
	elif target_level >= 36 and target_level <= 40:
		hell_modifier = 1.2
	elif target_level >= 41 and target_level <= 45:
